/**
 * <relative-time> — renders a human-readable relative timestamp from an
 * ISO `datetime` attribute and keeps itself fresh with an adaptive timer.
 *
 * Cadence: every 10s while under a minute, every minute while under an
 * hour, otherwise hourly. The timer is torn down in disconnectedCallback
 * and restarted whenever `datetime` changes.
 */
export class RelativeTimeElement extends HTMLElement {
  static get observedAttributes(): string[] {
    return ['datetime'];
  }

  #timer: ReturnType<typeof setInterval> | undefined;
  #rtf: Intl.RelativeTimeFormat;

  constructor() {
    super();
    this.#rtf = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
  }

  connectedCallback(): void {
    this.render();
    this.#startTimer();
  }

  disconnectedCallback(): void {
    this.#stopTimer();
  }

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (name === 'datetime' && oldValue !== newValue && this.isConnected) {
      this.render();
      this.#startTimer(); // new date may fall into a different cadence bucket
    }
  }

  /** The parsed date from the `datetime` attribute, or null if absent/invalid. */
  get date(): Date | null {
    const raw = this.getAttribute('datetime');
    if (!raw) return null;
    const d = new Date(raw);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  /** Pick the best unit for the elapsed time and format it. */
  #bestUnit(diffSeconds: number): { unit: Intl.RelativeTimeFormatUnit; value: number } {
    const abs = Math.abs(diffSeconds);
    if (abs < 60) return { unit: 'second', value: diffSeconds };
    if (abs < 3600) return { unit: 'minute', value: Math.round(diffSeconds / 60) };
    if (abs < 86400) return { unit: 'hour', value: Math.round(diffSeconds / 3600) };
    if (abs < 86400 * 30) return { unit: 'day', value: Math.round(diffSeconds / 86400) };
    if (abs < 86400 * 365) return { unit: 'month', value: Math.round(diffSeconds / (86400 * 30)) };
    return { unit: 'year', value: Math.round(diffSeconds / (86400 * 365)) };
  }

  render(): void {
    const date = this.date;
    if (!date) {
      this.textContent = '';
      this.removeAttribute('title');
      return;
    }
    const diffSeconds = (date.getTime() - Date.now()) / 1000; // negative for the past
    const { unit, value } = this.#bestUnit(diffSeconds);
    this.textContent = this.#rtf.format(value, unit);
    this.setAttribute('title', date.toLocaleString('en-US'));
  }

  /** Interval adapts to the current unit: 10s under a minute, 60s under an hour, else hourly. */
  #intervalMs(): number {
    const date = this.date;
    if (!date) return 60_000;
    const absSeconds = Math.abs((date.getTime() - Date.now()) / 1000);
    if (absSeconds < 60) return 10_000;
    if (absSeconds < 3600) return 60_000;
    return 3_600_000;
  }

  #startTimer(): void {
    this.#stopTimer();
    this.#timer = setInterval(() => this.render(), this.#intervalMs());
  }

  #stopTimer(): void {
    if (this.#timer !== undefined) {
      clearInterval(this.#timer);
      this.#timer = undefined;
    }
  }
}

if (!customElements.get('relative-time')) {
  customElements.define('relative-time', RelativeTimeElement);
}

