import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import './relative-time.js';

const NOW = new Date('2024-06-15T12:00:00Z').getTime();

function el(iso: string): HTMLElement {
  const e = document.createElement('relative-time');
  e.setAttribute('datetime', iso);
  document.body.appendChild(e);
  return e;
}

function iso(msAgo: number): string {
  return new Date(NOW - msAgo).toISOString();
}

describe('<relative-time>', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(NOW);
  });

  afterEach(() => {
    document.body.innerHTML = '';
    vi.useRealTimers();
  });

  describe('initial render across unit boundaries', () => {
    const cases = [
      { secondsAgo: 45, expected: '45 seconds ago' },
      { secondsAgo: 5 * 60, expected: '5 minutes ago' },
      { secondsAgo: 3 * 3600, expected: '3 hours ago' },
      { secondsAgo: 2 * 86400, expected: '2 days ago' },
    ];

    for (const { secondsAgo, expected } of cases) {
      it(`renders "${expected}" for ${secondsAgo}s ago`, () => {
        const e = el(iso(secondsAgo * 1000));
        expect(e.textContent).toBe(expected);
        // title carries the absolute time
        expect(e.getAttribute('title')).toBe(
          new Date(NOW - secondsAgo * 1000).toLocaleString('en-US'),
        );
      });
    }
  });

  describe('adaptive re-render cadence', () => {
    it('ticks every 10s while under a minute', () => {
      const e = el(iso(45_000));
      expect(e.textContent).toBe('45 seconds ago');

      // nothing at 9s
      vi.advanceTimersByTime(9_000);
      expect(e.textContent).toBe('45 seconds ago');

      // ticks at 10s
      vi.advanceTimersByTime(1_000);
      expect(e.textContent).toBe('55 seconds ago');

      // keeps ticking on the 10s grid, crossing into the next unit
      vi.advanceTimersByTime(10_000);
      expect(e.textContent).toBe('1 minute ago');
    });

    it('ticks every minute once under an hour', () => {
      const e = el(iso(5 * 60_000));
      expect(e.textContent).toBe('5 minutes ago');

      // no 10-second-granularity tick: still stale after 59s
      vi.advanceTimersByTime(59_000);
      expect(e.textContent).toBe('5 minutes ago');

      // the single minute tick fires and refreshes
      vi.advanceTimersByTime(1_000);
      expect(e.textContent).toBe('6 minutes ago');
    });

    it('ticks hourly otherwise', () => {
      const e = el(iso(3 * 3_600_000));
      expect(e.textContent).toBe('3 hours ago');

      vi.advanceTimersByTime(59 * 60_000);
      expect(e.textContent).toBe('3 hours ago');

      vi.advanceTimersByTime(60_000);
      expect(e.textContent).toBe('4 hours ago');
    });
  });

  describe('cleanup', () => {
    it('stops its timer on disconnect (clearInterval spy)', () => {
      const clearIntervalSpy = vi.spyOn(globalThis, 'clearInterval');
      const e = el(iso(45_000));

      const timersBefore = vi.getTimerCount();
      expect(timersBefore).toBeGreaterThan(0);

      e.remove();

      expect(clearIntervalSpy).toHaveBeenCalled();
      expect(vi.getTimerCount()).toBe(timersBefore - 1);

      // and it stays frozen: no re-render despite time passing
      vi.advanceTimersByTime(10 * 60_000);
      expect(e.textContent).toBe('45 seconds ago');
    });
  });

  describe('attribute change', () => {
    it('re-renders when datetime changes', () => {
      const e = el(iso(45_000));
      expect(e.textContent).toBe('45 seconds ago');

      e.setAttribute('datetime', iso(3 * 3_600_000));
      expect(e.textContent).toBe('3 hours ago');
      expect(e.getAttribute('title')).toBe(new Date(NOW - 3 * 3_600_000).toLocaleString('en-US'));
    });

    it('adapts the cadence bucket to the new value', () => {
      const e = el(iso(45_000)); // 10s bucket

      // after switching to 5 minutes ago, a 10s advance must NOT tick...
      e.setAttribute('datetime', iso(5 * 60_000));
      vi.advanceTimersByTime(10_000);
      expect(e.textContent).toBe('5 minutes ago');

      // ...but the minute tick does
      vi.advanceTimersByTime(50_000);
      expect(e.textContent).toBe('6 minutes ago');
    });

    it('ignores setting the same value again', () => {
      const e = el(iso(45_000));
      const clearIntervalSpy = vi.spyOn(globalThis, 'clearInterval');
      e.setAttribute('datetime', e.getAttribute('datetime')!);
      expect(clearIntervalSpy).not.toHaveBeenCalled();
      expect(e.textContent).toBe('45 seconds ago');
    });
  });
});

